-- Period study v2; read-only; 2026-09-05 through 2026-09-11 Asia/Shanghai.
-- Observation frame uses ended lessons in the available daily partitions.
-- See report for snapshot, completeness and denominator limitations.
WITH frame AS (SELECT school_uid,COUNT(1) AS scheduled_n,SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END) AS opened_n,SUM(CASE WHEN class_status=4 THEN 1 ELSE 0 END) AS cancelled_n FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND school_uid>0 GROUP BY school_uid HAVING SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END)>0), thresholds AS (SELECT percentile_approx(opened_n,0.3333333333) AS q1,percentile_approx(opened_n,0.6666666667) AS q2 FROM frame), strat AS (SELECT f.school_uid,f.scheduled_n,f.opened_n,f.cancelled_n,CASE WHEN f.opened_n<=t.q1 THEN 'low' WHEN f.opened_n<=t.q2 THEN 'mid' ELSE 'high' END AS stratum,t.q1,t.q2 FROM frame f CROSS JOIN thresholds t), ranked AS (SELECT school_uid,stratum,opened_n,ROW_NUMBER() OVER(PARTITION BY stratum ORDER BY md5(concat('20260912:',CAST(school_uid AS STRING))),school_uid) AS rn FROM strat) SELECT school_uid,stratum,opened_n FROM ranked WHERE rn<=4 ORDER BY stratum,rn LIMIT 12;
